public record WarehouseInfo(string Id, string Name)
{
    public static readonly WarehouseInfo[] All =
    [
        new("WH-A", "Warehouse A"),
        new("WH-B", "Warehouse B"),
        new("WH-C", "Warehouse C"),
    ];

    public static WarehouseInfo Default => All[0];
}

namespace sv_f375549db88d44649e7e29e768f9cbb7.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts per circuit.
/// Components subscribe to <see cref="OnChange"/> to react when new data arrives.
/// </summary>
public sealed class InventoryAlertService
{
    private readonly Random _random = new();

    public int LatestCount { get; private set; }

    public event Action? OnChange;

    /// <summary>Simulates a database query returning the number of low-stock items.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        // Simulate varying results per warehouse by seeding off the id hash.
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches fresh data and notifies all subscribers.
    /// Called by whichever component owns the polling loop.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        LatestCount = await GetLowStockCountAsync(warehouseId);
        OnChange?.Invoke();
    }
}

