@using sv_f375549db88d44649e7e29e768f9cbb7.Services
@rendermode InteractiveServer

@inject CascadingValueSource<WarehouseInfo> WarehouseSource

<div class="d-flex align-items-center">
    <label class="me-2 text-nowrap fw-semibold">Warehouse:</label>
    <select class="form-select form-select-sm" style="width:auto"
            value="@_selectedId" @onchange="OnWarehouseChanged">
        @foreach (var wh in WarehouseInfo.All)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    private string _selectedId = WarehouseInfo.Default.Id;

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        _selectedId = e.Value?.ToString() ?? WarehouseInfo.Default.Id;
        var selected = WarehouseInfo.All.First(w => w.Id == _selectedId);
        await WarehouseSource.NotifyChangedAsync(selected);
    }
}

@using sv_f375549db88d44649e7e29e768f9cbb7.Services
@rendermode InteractiveServer
@implements IDisposable

@inject InventoryAlertService AlertService

<span class="badge rounded-pill @(_count > 0 ? "bg-danger" : "bg-secondary")">
    @_count
</span>

@code {
    private int _count;
    private Action? _handler;

    protected override void OnInitialized()
    {
        _count = AlertService.LatestCount;
        _handler = () => InvokeAsync(() =>
        {
            _count = AlertService.LatestCount;
            StateHasChanged();
        });
        AlertService.OnChange += _handler;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
    }
}

