@page "/dashboard"
@using sv_f375549db88d44649e7e29e768f9cbb7.Services
@rendermode InteractiveServer
@implements IDisposable

@inject InventoryAlertService AlertService

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<p>
    Monitoring: <strong>@Warehouse?.Name</strong>
</p>

<div class="card" style="max-width: 20rem;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text display-4 @(_alertCount > 0 ? "text-danger" : "text-success")">
            @_alertCount
        </p>
        <p class="text-muted">items below minimum level</p>
        <p class="text-muted small">Refreshes every 10 seconds</p>
    </div>
</div>

@code {
    [CascadingParameter]
    private WarehouseInfo? Warehouse { get; set; }

    private int _alertCount;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Subscribe so we also update when another component triggers a refresh.
        _handler = () => InvokeAsync(() =>
        {
            _alertCount = AlertService.LatestCount;
            StateHasChanged();
        });
        AlertService.OnChange += _handler;
    }

    protected override async Task OnParametersSetAsync()
    {
        // Restart polling whenever the selected warehouse changes.
        await StopPollingAsync();
        await StartPollingAsync();
    }

    private async Task StartPollingAsync()
    {
        if (Warehouse is null) return;

        // Do an immediate first fetch.
        await AlertService.RefreshAsync(Warehouse.Id);
        _alertCount = AlertService.LatestCount;

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));

        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                if (Warehouse is not null)
                {
                    // RefreshAsync updates LatestCount and fires OnChange,
                    // which notifies the AlertBadge in the sidebar too.
                    await AlertService.RefreshAsync(Warehouse.Id);
                }
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose / warehouse switch.
        }
    }

    private async Task StopPollingAsync()
    {
        if (_cts is not null)
        {
            await _cts.CancelAsync();
            _cts.Dispose();
            _cts = null;
        }
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        AlertService.OnChange -= _handler;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}

